func newTeamViewerRemoteAdministrationsPatchCmd(ctx *registry.CLIContext) *cobra.Command {
	var (
		flagScaffold bool
		flagSet      []string
		fromFile     string
		flagName     string
	)

	cmd := &cobra.Command{
		Use:   "patch [<id>]",
		Short: "Update Team Viewer Remote Administration connection configuration",
		Long:  "Updates Team Viewer Remote Administration connection configuration\n\nIdentify the resource by ID (positional arg), --name, . Omit ID to use a lookup flag.\n\nUse --set KEY=VALUE to update scalar fields (repeatable). Omitted fields are unchanged.\n\nAvailable fields:\n  displayName                                  string\n  enabled                                      boolean\n  sessionTimeout                               integer\n  token                                        string\n\nUse --from-file or pipe JSON to stdin for complex updates (arrays, bulk changes).",
		Example: `  # Update a field by ID
  jamf-cli pro team-viewer-remote-administrations patch 1 --set general.managed=true

  # Update multiple fields
  jamf-cli pro team-viewer-remote-administrations patch 1 --set field1=value1 --set field2=value2

  # Update by name
  jamf-cli pro team-viewer-remote-administrations patch --name "Example" --set general.managed=true

  # Patch from a file
  jamf-cli pro team-viewer-remote-administrations patch 1 --from-file changes.json`,
		Annotations: map[string]string{"jamf:privileges": "Update Remote Administration"},
		Args:        cobra.MaximumNArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			reqCtx := cmd.Context()

			if flagScaffold {
				return printScaffoldOutput(`{
  "displayName": "teamViewerConfiguration",
  "enabled": true,
  "sessionTimeout": 15,
  "token": "12843140-nPAX96bsaADH4Gz6K6i2"
}`, ctx.Output.Format())
			}

			// Resolve resource ID from positional arg, --name, or lookup flags
			var resolvedPatchID string
			if flagName != "" {
				rid, err := resolveNameToID(reqCtx, ctx.Client, "/preview/remote-administration-configurations/team-viewer", "displayName", "id", flagName)
				if err != nil {
					return err
				}
				resolvedPatchID = rid
			} else if len(args) > 0 {
				resolvedPatchID = args[0]
			} else {
				return fmt.Errorf("provide an <id> argument, --name")
			}

			// Build request path
			path := "/preview/remote-administration-configurations/team-viewer/{id}"
			path = strings.Replace(path, "{id}", url.PathEscape(resolvedPatchID), 1)

			// Build query string
			var queryParts []string
			if len(queryParts) > 0 {
				path = path + "?" + strings.Join(queryParts, "&")
			}

			// Make request
			// Read body from stdin if available
			var body io.Reader
			// PATCH: --set flags take priority; fall back to --from-file or stdin
			reqCtx = registry.WithContentType(reqCtx, "application/merge-patch+json")
			var normalized []byte
			switch {
			case len(flagSet) > 0:
				data, err := buildMergePatchFromSet(flagSet)
				if err != nil {
					return err
				}
				normalized = data
			case fromFile != "":
				data, err := os.ReadFile(fromFile)
				if err != nil {
					return fmt.Errorf("reading input file: %w", err)
				}
				normalized = data
			default:
				stat, _ := os.Stdin.Stat()
				if (stat.Mode() & os.ModeCharDevice) == 0 {
					raw, err := io.ReadAll(io.LimitReader(os.Stdin, 10<<20))
					if err != nil {
						return fmt.Errorf("reading stdin: %w", err)
					}
					normalized = raw
				}
			}
			if len(normalized) > 0 {
				body = bytes.NewReader(normalized)
			}
			resp, err := ctx.Client.Do(reqCtx, "PATCH", path, body)
			if err != nil {
				return err
			}
			defer resp.Body.Close()

			return ctx.Output.PrintResponse(resp)
		},
	}

	cmd.Flags().BoolVar(&flagScaffold, "scaffold", false, "Print a JSON template for the request body and exit")
	cmd.Flags().StringArrayVar(&flagSet, "set", nil, "Set a field value in dot notation (key=value, repeatable)")
	cmd.Flags().StringVar(&fromFile, "from-file", "", "Path to JSON merge-patch file (or pipe to stdin)")
	_ = cmd.RegisterFlagCompletionFunc("set", func(_ *cobra.Command, _ []string, _ string) ([]string, cobra.ShellCompDirective) {
		return []string{
			"displayName=", "enabled=", "sessionTimeout=", "token=",
		}, cobra.ShellCompDirectiveNoSpace
	})
	cmd.Flags().StringVar(&flagName, "name", "", "Look up team-viewer-remote-administration by name")

	return cmd
}

